(function() {
  'use strict';

  const isMusicPlayerPage = () => {
    return window.location.pathname.startsWith('/!0');
  };

  const SpectrumColorSync = {
    config: {
      enabled: true,
      intensity: 0.6,
      transitionSpeed: 'fast',
      affectCards: true,
      affectButtons: true,
      affectProgress: true,
      affectBackground: true,
      pulseOnBeat: true
    },

    currentColor: '#81D4FA',
    lastAppliedColor: null,
    observer: null,
    styleElement: null,
    isRunning: false,
    colorChangeHandler: null,
    animationFrameId: null,

    init() {
      console.log('频谱色彩同步插件已加载 v1.2.0');
      this.loadConfig();

      window.addEventListener('plugin-settings-updated', (e) => {
        if (e.detail.pluginId === 'music-player-spectrum-sync-1733600000000') {
          this.config = { ...this.config, ...e.detail.settings };
          if (this.config.enabled && isMusicPlayerPage()) {
            this.start();
          } else {
            this.stop();
          }
        }
      });

      this.createStyleElement();
      this.watchRoute();

      if (isMusicPlayerPage() && this.config.enabled) {
        setTimeout(() => this.start(), 500);
      }
    },

    watchRoute() {
      const handleRouteChange = () => {
        setTimeout(() => {
          if (isMusicPlayerPage() && this.config.enabled) {
            this.start();
          } else {
            this.stop();
          }
        }, 300);
      };

      window.addEventListener('popstate', handleRouteChange);

      const originalPushState = history.pushState;
      const originalReplaceState = history.replaceState;

      history.pushState = function(...args) {
        originalPushState.apply(history, args);
        handleRouteChange();
      };

      history.replaceState = function(...args) {
        originalReplaceState.apply(history, args);
        handleRouteChange();
      };
    },

    start() {
      if (this.isRunning) return;
      this.isRunning = true;
      console.log('频谱色彩同步启动');
      this.startColorSync();
      this.observeDOM();
    },

    stop() {
      if (!this.isRunning) return;
      this.isRunning = false;
      console.log('频谱色彩同步停止');
      this.cleanup();
    },

    loadConfig() {
      console.log('使用数据库存储的全局配置');
    },

    createStyleElement() {
      if (this.styleElement) return;
      this.styleElement = document.createElement('style');
      this.styleElement.id = 'spectrum-color-sync-styles';
      document.head.appendChild(this.styleElement);
    },

    startColorSync() {
      // 监听频谱颜色变化事件
      this.colorChangeHandler = (e) => {
        if (!this.isRunning || !e.detail || !e.detail.color) return;
        this.updateColor(e.detail.color);
      };

      window.addEventListener('spectrum-color-change', this.colorChangeHandler);

      // 使用 requestAnimationFrame 进行更高频率的颜色监听
      if (this.config.transitionSpeed === 'instant') {
        const checkColorUpdate = () => {
          if (!this.isRunning) return;
          const root = document.documentElement;
          const currentCSSColor = getComputedStyle(root).getPropertyValue('--aero-primary').trim();
          if (currentCSSColor && currentCSSColor !== this.lastAppliedColor) {
            this.currentColor = currentCSSColor;
            this.lastAppliedColor = currentCSSColor;
            this.applyColors();
          }
          this.animationFrameId = requestAnimationFrame(checkColorUpdate);
        };
        checkColorUpdate();
      }

      // 初始化时应用一次
      const root = document.documentElement;
      const initialColor = getComputedStyle(root).getPropertyValue('--aero-primary').trim();
      if (initialColor) {
        this.currentColor = initialColor;
        this.lastAppliedColor = initialColor;
        this.applyColors();
      }
    },

    // 暴露给频谱渲染直接调用的同步更新函数
    updateColor(newColor) {
      if (!this.isRunning || !newColor) return;

      // 避免重复应用相同的颜色
      if (newColor === this.lastAppliedColor) return;

      this.currentColor = newColor;
      this.lastAppliedColor = newColor;
      this.applyColors();
    },

    applyColors() {
      if (!this.config.enabled || !this.styleElement) return;

      const color = this.currentColor;
      const intensity = this.config.intensity;
      const speed = this.getTransitionSpeed();

      const rgb = this.parseColor(color);
      if (!rgb) return;

      const { r, g, b } = rgb;

      const colorLight = 'rgba(' + r + ', ' + g + ', ' + b + ', ' + (0.1 * intensity) + ')';
      const colorMedium = 'rgba(' + r + ', ' + g + ', ' + b + ', ' + (0.3 * intensity) + ')';
      const colorStrong = 'rgba(' + r + ', ' + g + ', ' + b + ', ' + (0.6 * intensity) + ')';

      // 对于实时同步模式，完全禁用CSS过渡
      // 对于快速模式，使用极短的过渡时间
      const actualSpeed = speed;

      let styles = '\n        /* 基础过渡设置 */\n        .player-wrapper *:not(.lyric-line):not(.lyrics-container) {\n          transition: ' + (actualSpeed === '0s' ? 'none' : 'border-color ' + actualSpeed + ', background-color ' + actualSpeed + ', box-shadow ' + actualSpeed + ', color ' + actualSpeed) + ' !important;\n        }\n      ';

      if (this.config.affectCards) {
        styles += '\n          .player-wrapper .v-card {\n            border-color: ' + colorMedium + ' !important;\n            box-shadow: 0 4px 20px ' + colorLight + ', inset 0 1px 0 ' + colorMedium + ' !important;\n          }\n          \n          .player-wrapper .v-card:hover {\n            box-shadow: 0 8px 30px ' + colorMedium + ', inset 0 1px 0 ' + colorStrong + ' !important;\n          }\n          \n          .player-wrapper .playlist-item.active {\n            background-color: ' + colorLight + ' !important;\n            border-color: ' + colorMedium + ' !important;\n            box-shadow: 0 0 20px ' + colorLight + ' !important;\n          }\n        ';
      }

      if (this.config.affectButtons) {
        styles += '\n          .player-wrapper .v-btn--variant-elevated,\n          .player-wrapper .v-btn--variant-flat {\n            background: linear-gradient(135deg, ' + colorMedium + ', ' + colorLight + ') !important;\n          }\n          \n          .player-wrapper .v-btn--variant-elevated:hover,\n          .player-wrapper .v-btn--variant-flat:hover {\n            background: linear-gradient(135deg, ' + colorStrong + ', ' + colorMedium + ') !important;\n            box-shadow: 0 4px 15px ' + colorMedium + ' !important;\n          }\n          \n          .player-wrapper .v-btn[color=\"primary\"] {\n            background: ' + color + ' !important;\n            box-shadow: 0 0 20px ' + colorMedium + ' !important;\n          }\n        ';
      }

      if (this.config.affectProgress) {
        styles += '\n          /* Vuetify滑块整体组件 */\n          .player-wrapper .v-slider {\n            color: ' + color + ' !important;\n          }\n          \n          /* 滑块已填充轨道 */\n          .player-wrapper .v-slider .v-slider-track__fill {\n            background-color: ' + color + ' !important;\n          }\n          \n          /* 滑块背景轨道 */\n          .player-wrapper .v-slider .v-slider-track__background {\n            opacity: 0.3 !important;\n            background-color: ' + colorMedium + ' !important;\n          }\n          \n          /* 滑块拖动按钮 */\n          .player-wrapper .v-slider .v-slider-thumb__surface {\n            background-color: ' + color + ' !important;\n            box-shadow: 0 0 10px ' + colorMedium + ' !important;\n          }\n          \n          /* 兼容旧版Vuetify类名 */\n          .player-wrapper .v-slider__track-fill {\n            background: ' + color + ' !important;\n          }\n          \n          .player-wrapper .v-slider__track-background {\n            opacity: 0.3 !important;\n            background: ' + colorLight + ' !important;\n          }\n          \n          .player-wrapper .v-slider__thumb {\n            background: ' + color + ' !important;\n            box-shadow: 0 0 10px ' + colorMedium + ' !important;\n          }\n          \n          /* 进度条 */\n          .player-wrapper .v-progress-linear__determinate {\n            background: linear-gradient(90deg, ' + colorLight + ', ' + color + ') !important;\n          }\n        ';
      }

      if (this.config.affectBackground) {
        styles += '\n          .player-wrapper .player-container {\n            background: radial-gradient(circle at 50% 50%, ' + colorLight + ', transparent 70%) !important;\n          }\n        ';
      }

      styles += '\n        .player-wrapper .lyric-line.active {\n          color: ' + color + ' !important;\n          text-shadow: 0 0 20px ' + colorMedium + ' !important;\n        }\n      ';

      if (this.config.pulseOnBeat) {
        styles += '\n          @keyframes spectrum-pulse {\n            0% { transform: scale(1); box-shadow: 0 0 0 ' + colorMedium + '; }\n            50% { transform: scale(1.05); box-shadow: 0 0 30px ' + colorStrong + '; }\n            100% { transform: scale(1); box-shadow: 0 0 0 ' + colorMedium + '; }\n          }\n          \n          .player-wrapper .spectrum-pulse {\n            animation: spectrum-pulse 0.3s ease-out !important;\n          }\n        ';
      }

      this.styleElement.textContent = styles;
    },

    parseColor(color) {
      if (color.startsWith('rgba') || color.startsWith('rgb')) {
        const match = color.match(/\d+/g);
        if (match && match.length >= 3) {
          return {
            r: parseInt(match[0]),
            g: parseInt(match[1]),
            b: parseInt(match[2])
          };
        }
      }

      if (color.startsWith('#')) {
        const hex = color.replace('#', '');
        return {
          r: parseInt(hex.substring(0, 2), 16),
          g: parseInt(hex.substring(2, 4), 16),
          b: parseInt(hex.substring(4, 6), 16)
        };
      }

      return null;
    },

    getTransitionSpeed() {
      const speeds = {
        instant: '0s',
        fast: '0.05s',
        normal: '0.3s',
        slow: '0.6s'
      };
      return speeds[this.config.transitionSpeed] || speeds.fast;
    },

    observeDOM() {
      if (this.observer) return;

      this.observer = new MutationObserver(() => {
        if (this.config.enabled && isMusicPlayerPage()) {
          this.applyColors();
        }
      });

      this.observer.observe(document.body, {
        childList: true,
        subtree: true
      });
    },

    cleanup() {
      if (this.styleElement) {
        this.styleElement.textContent = '';
      }
      if (this.observer) {
        this.observer.disconnect();
        this.observer = null;
      }
      if (this.colorChangeHandler) {
        window.removeEventListener('spectrum-color-change', this.colorChangeHandler);
        this.colorChangeHandler = null;
      }
      if (this.animationFrameId) {
        cancelAnimationFrame(this.animationFrameId);
        this.animationFrameId = null;
      }
    }
  };

  window.spectrumColorSync = SpectrumColorSync;
  SpectrumColorSync.init();

  window.addEventListener('beforeunload', () => {
    SpectrumColorSync.cleanup();
  });
})();

