/* 频谱色彩同步插件的基础样式 */

.player-wrapper {
  position: relative;
}

/* 为节奏脉冲做准备 */
.player-wrapper .v-btn,
.player-wrapper .v-card,
.player-wrapper .playlist-item {
  will-change: transform, box-shadow;
}

/* 保留歌词的原始动画 */
.player-wrapper .lyric-line {
  transition: all 0.3s ease !important;
}

.player-wrapper .lyric-line.active {
  will-change: color, text-shadow, transform;
}

/* 保留歌词容器的淡入淡出动画 */
.player-wrapper .lyrics-container {
  transition: opacity 0.3s ease !important;
}

/* 确保颜色变化立即生效（实时同步模式） */
.player-wrapper.instant-sync *:not(.lyric-line):not(.lyrics-container) {
  transition: none !important;
}

.player-wrapper .v-btn[size="large"] {
  position: relative;
  overflow: visible;
}
